//! Append-only, workspace-scoped activity records for real local changes.
//! Event summaries are generated by trusted services; no raw user content,
//! credentials, task descriptions or arbitrary metadata enter the event store.

use rusqlite::{params, Transaction};
use uuid::Uuid;

#[derive(Debug, Clone, Copy)]
pub enum ActivityEntityKind {
    Project,
    Task,
}

impl ActivityEntityKind {
    fn values(self) -> (&'static str, &'static str) {
        match self {
            Self::Project => ("project", "Project created"),
            Self::Task => ("task", "Task created"),
        }
    }
}

/// Called inside the entity's existing transaction: no partial entity/event pair.
pub fn record_creation(
    transaction: &Transaction<'_>,
    workspace_id: &str,
    kind: ActivityEntityKind,
    entity_id: &str,
) -> Result<(), String> {
    let (entity_type, summary) = kind.values();
    let project_id = (entity_type == "project").then_some(entity_id);
    let task_id = (entity_type == "task").then_some(entity_id);
    transaction
        .execute(
            "INSERT INTO activity_events
                (id, workspace_id, entity_type, entity_id,
                 project_id, task_id, action, summary)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, 'created', ?7)",
            params![
                Uuid::new_v4().to_string(),
                workspace_id,
                entity_type,
                entity_id,
                project_id,
                task_id,
                summary
            ],
        )
        .map_err(|_| "IO_ERROR: could not record activity event".to_string())?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{projects, tasks};
    use rusqlite::Connection;

    const PERSONAL: &str = "00000000-0000-4000-8000-000000000001";

    fn fixture() -> Connection {
        let mut connection = Connection::open_in_memory().expect("disposable database");
        connection
            .execute_batch("PRAGMA foreign_keys = ON;")
            .expect("enable foreign keys");
        crate::run_migrations(&mut connection).expect("schema");
        connection
    }

    #[test]
    fn project_and_task_creates_persist_real_scoped_activity_without_user_text() {
        let mut connection = fixture();
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Sensitive project name".to_string(),
                project_key: None,
                description: Some("secret-description-never-audit".to_string()),
                goal: None,
                status: None,
            },
        )
        .expect("project with event");
        let task = tasks::create_task(
            &mut connection,
            tasks::CreateTask {
                workspace_id: PERSONAL.to_string(),
                project_id: Some(project.id.clone()),
                title: "Sensitive task title".to_string(),
                description: Some("secret-task-description".to_string()),
                status: None,
                priority: None,
            },
        )
        .expect("task with event");

        let mut statement = connection
            .prepare(
                "SELECT workspace_id, entity_type, entity_id, action, summary,
                        occurred_at, sensitivity, actor_type
                 FROM activity_events ORDER BY rowid",
            )
            .expect("activity query");
        let events: Vec<(String, String, String, String, String, String, String, String)> =
            statement
                .query_map([], |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                        row.get(5)?,
                        row.get(6)?,
                        row.get(7)?,
                    ))
                })
                .expect("rows")
                .map(|row| row.expect("row"))
                .collect();
        assert_eq!(events.len(), 2);
        assert_eq!(events[0].0, PERSONAL);
        assert_eq!(events[0].1, "project");
        assert_eq!(events[0].2, project.id);
        assert_eq!(events[1].1, "task");
        assert_eq!(events[1].2, task.id);
        assert_eq!(events[0].3, "created");
        assert_eq!(events[1].3, "created");
        assert_eq!(events[0].4, "Project created");
        assert_eq!(events[1].4, "Task created");
        for event in events {
            assert!(event.5.ends_with('Z'), "activity timestamp uses UTC");
            assert!(!event.5.is_empty());
            assert_eq!(event.6, "normal");
            assert_eq!(event.7, "local");
            assert!(!event.4.contains("secret"));
            assert!(!event.4.contains("Sensitive"));
        }
    }

    #[test]
    fn activity_schema_rejects_missing_or_cross_workspace_entity_references() {
        let mut connection = fixture();
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Valid".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("fixture project");
        connection
            .execute(
                "INSERT INTO workspaces (id, name) VALUES ('other', 'Other')",
                [],
            )
            .expect("other workspace");
        assert!(connection
            .execute(
                "INSERT INTO activity_events
                    (id, workspace_id, entity_type, entity_id, project_id, action, summary)
                 VALUES ('wrong-workspace', 'other', 'project', ?1, ?1, 'created', 'Safe')",
                params![project.id],
            )
            .is_err());
        assert!(connection
            .execute(
                "INSERT INTO activity_events
                    (id, workspace_id, entity_type, entity_id, project_id, action, summary)
                 VALUES ('missing-project', ?1, 'project', 'missing', 'missing', 'created', 'Safe')",
                params![PERSONAL],
            )
            .is_err());
        assert!(connection
            .execute(
                "INSERT INTO activity_events
                    (id, workspace_id, entity_type, entity_id, project_id, action, summary)
                 VALUES ('mismatch', ?1, 'project', 'wrong-id', ?2, 'created', 'Safe')",
                params![PERSONAL, project.id],
            )
            .is_err());
        let count: i64 = connection
            .query_row("SELECT COUNT(*) FROM activity_events", [], |row| row.get(0))
            .expect("event count");
        assert_eq!(count, 1, "invalid attempts cannot append activity");
    }

    #[test]
    fn failed_event_write_rolls_back_project_and_task_creation() {
        let mut connection = fixture();
        connection
            .execute_batch(
                "CREATE TRIGGER reject_activity
                 BEFORE INSERT ON activity_events
                 BEGIN
                     SELECT RAISE(ABORT, 'synthetic activity failure');
                 END;",
            )
            .expect("failure injection");
        let project_error = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Will rollback".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect_err("event failure must abort entity transaction");
        assert!(project_error.starts_with("IO_ERROR:"));
        let count: i64 = connection
            .query_row("SELECT COUNT(*) FROM projects", [], |row| row.get(0))
            .unwrap();
        assert_eq!(count, 0);
        connection
            .execute_batch("DROP TRIGGER reject_activity")
            .expect("remove injection");
        let project = projects::create_project(
            &mut connection,
            projects::CreateProject {
                workspace_id: PERSONAL.to_string(),
                name: "Good".to_string(),
                project_key: None,
                description: None,
                goal: None,
                status: None,
            },
        )
        .expect("create allowed project");
        connection
            .execute_batch(
                "CREATE TRIGGER reject_activity
                 BEFORE INSERT ON activity_events
                 BEGIN
                     SELECT RAISE(ABORT, 'synthetic activity failure');
                 END;",
            )
            .expect("restore injection");
        let task_error = tasks::create_task(
            &mut connection,
            tasks::CreateTask {
                workspace_id: PERSONAL.to_string(),
                project_id: Some(project.id),
                title: "Rollback task".to_string(),
                description: None,
                status: None,
                priority: None,
            },
        )
        .expect_err("task and event must commit together");
        assert!(task_error.starts_with("IO_ERROR:"));
        let task_count: i64 = connection
            .query_row("SELECT COUNT(*) FROM tasks", [], |row| row.get(0))
            .unwrap();
        assert_eq!(task_count, 0);
    }
}
